$cents=static fn($v):int=>(int)str_replace('.','',(string)$v);
$totalQty=0;foreach($record['items'] as $line)$totalQty+=(int)$line['quantity']+(int)$line['free_quantity'];
$changeCents=0;foreach($record['receipts'] as $r)$changeCents+=$cents($r['change_amount']);
