$hasDiscount=$cents($record['discount_total']??'0.00')>0;
$fmtPct=static function($v):string{return rtrim(rtrim(number_format((float)$v,2,'.',''),'0'),'.').'%';};
$rateCents=0;$ratePct=null;
if($cents($record['invoice_discount_amount']??'0.00')>0&&isset($record['invoice_discount_percent'])&&(float)$record['invoice_discount_percent']>0){$rateCents=$cents($record['invoice_discount_amount']);$ratePct=$fmtPct($record['invoice_discount_percent']);}
elseif(($record['benefit_mode']??'')!==''&&($record['benefit_mode']??'')!=='FREE_PROMOTION'&&$cents($record['benefit_discount_amount']??'0.00')>0&&isset($record['benefit_percent_rate'])&&(float)$record['benefit_percent_rate']>0){$rateCents=$cents($record['benefit_discount_amount']);$ratePct=$fmtPct($record['benefit_percent_rate']);}
$totalDiscCents=$cents($record['discount_total']??'0.00');$otherCents=max(0,$totalDiscCents-$rateCents);
