<?php else: ?><table class="invoice-items"><thead><tr><th><?= $I('Product') ?></th><th><?= $I('Qty') ?></th><th><?= $I('Free') ?></th><th><?= $I('Price') ?></th><th><?= $I('Amount') ?></th></tr></thead><tbody><?php foreach($record['items'] as $line): ?><tr><td><strong><?= $e(\App\Support\I18n::product($line)) ?></strong></td><td><?= $e($line['quantity']) ?></td><td><?= $e($line['free_quantity']) ?></td><td><?= $money($line['unit_price']) ?></td><td><?= $money($line['gross_amount']) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
